function SearchField(field) {
    var str = '';
    str = $("#txt" + field).val();
    str = str.toLowerCase();
    $("input:checkbox[id=chk" + field + "]").each(function () {
        console.log($(this).val())
        if ($(this).val().toLowerCase().indexOf(str) >= 0 || str == '') {
            $(this).show();
            $(this).next().show();
        }
        else {
            $(this).hide();
            $(this).next().hide();
        }

    });
}
function candfilterPlainArray(array, filters) {
    const filterKeys = Object.keys(filters);
    return array.filter(item => {
        // validates all filter criteria
        return filterKeys.every(key => {
            // ignores an empty filter
            if (!filters[key].length) return true;
            return filters[key].find(filter => candgetValue(filter).toString() === candgetValue((item[key] == "" || item[key] == undefined || item[key] == null || item[key] == "null") && (item[key] != "0") ? "(Blanks)" : item[key]).toString());
        });
    });
}
const candgetValue = value => (typeof value === 'string' ? value.toUpperCase() : value);

